measures.expression:
// THis is leased occupancy
var filterName =   SELECTEDVALUE('Filter Toggles'[Filter Name], "Count")
RETURN
    SWITCH(filterName
            , "Count",  DIVIDE([# Occupied - Count or Area]-[# Holdover], ([# Occupied Units] + [# Vacant Units]))
            , "Area", DIVIDE([# Occupied - Count or Area] - [# Holdover - Count or Area] , ([# Lettable Area]))
            ,"Income (Net)" , [% Current Occupied Net Rent]- [% Holdover By Net Income]
            ,"Income (Gross)",DIVIDE([# Current Occupied Gross Rent]- [# Holdover Gross Income],[# Current Occupied + Vacant Gross Rent])
        , 0
    )

var futureStage = LOOKUPVALUE('Deal Stage'[Deal Display Name], 'Deal Stage'[Deal Stage SK], SELECTEDVALUE('Occupancies'[Next Deal Stage SK]))
RETURN
    IF(futureStage = "Unknown", "N/A", futureStage)

var filterName =   SELECTEDVALUE('Filter Toggles'[Filter Name], "Count")
RETURN
    SWITCH(filterName
            , "Count",  [# Occupancy All Units]
            , "Area", [# Lettable Area]
            //, "Income (Net)" , [# Current Occupied + Vacant Net Rent]
            //, "Income (Gross)" , [# Current Occupied + Vacant Gross Rent]
            , "Income (Net)", [# Occupancy All Units]
            , "Income (Gross)", [# Occupancy All Units]
        , 0
    )

var unit_ID = SELECTEDVALUE('Lease'[Unit ID])
RETURN
"https://mirvac.elevate.cafe/retailmanagernet/content/#/app/spacepage/" & unit_ID & "/summary"

var NextDealStage = SELECTEDVALUE('Deal Stage'[Deal Stage SK], -1)
var Deal = CALCULATE(MIN('Deal Stage'[Deal Stage Order]) , REMOVEFILTERS('Deal Stage'), 'Deal Stage'[Deal Stage Long] = "Deal")
var LAF = CALCULATE(MIN('Deal Stage'[Deal Stage Order]), REMOVEFILTERS('Deal Stage'), 'Deal Stage'[Deal Stage Long] = "LAF Submitted")
var Heads = CALCULATE(MIN('Deal Stage'[Deal Stage Order]), REMOVEFILTERS('Deal Stage'), 'Deal Stage'[Deal Stage Long] = "Heads Signed")
var ExcludeDeals = SWITCH(SELECTEDVALUE('Deal Stage'[Deal Stage], ""),
                        "Heads", Heads,
                        "LAF", LAF,
                        "Deal", Deal,
                        "N/A", 500
                    )


var EndDate = CALCULATE( SELECTEDVALUE('Lease Critical Dates'[Critical Date]),REMOVEFILTERS('Deal Stage'), 'Deal Stage'[Deal Stage Order]  < ExcludeDeals)
return
 DATEDIFF(TODAY() , EndDate, DAY)

var currentMonth =  CALCULATE(MAX('Calendar Reporting'[Month]), REMOVEFILTERS('Calendar Reporting'), 'Calendar Reporting'[Date] = TODAY())
var  SelectedFY = SELECTEDVALUE('Calendar Reporting'[Fiscal Year Name])
RETURN  [# Forecast Cashflow]
  + CALCULATE( [# Cashflow], 'Cashflow Type'[Cashflow Type] = "Actual", REMOVEFILTERS('Calendar Reporting') , 'Calendar Reporting'[Calendar SK] < currentMonth, 'Calendar Reporting'[Fiscal Year Name]=SelectedFY)

var currentMonth =  CALCULATE(MAX('Calendar Reporting'[Month]), REMOVEFILTERS('Calendar Reporting'), 'Calendar Reporting'[Date] = TODAY())
var  SelectedFY = SELECTEDVALUE('Calendar Reporting'[Fiscal Year Name])
RETURN
CALCULATE( [# Cashflow], 'Cashflow Type'[Cashflow Type] = "Actual", REMOVEFILTERS('Calendar Reporting') , 'Calendar Reporting'[Calendar SK] < currentMonth, 'Calendar Reporting'[Fiscal Year Name]=SelectedFY)
